package com.aistock.prediction.portfolioquestion;
import com.aistock.common.*;import com.aistock.prediction.security.*;import java.util.*;import org.junit.jupiter.api.*;import org.springframework.beans.factory.annotation.Autowired;import org.springframework.context.annotation.*;import org.springframework.test.context.junit.jupiter.SpringJUnitConfig;import org.springframework.test.context.web.WebAppConfiguration;import org.springframework.web.context.WebApplicationContext;import org.springframework.security.config.annotation.web.configuration.EnableWebSecurity;import org.springframework.mock.web.MockCookie;import org.springframework.test.web.servlet.*;import org.springframework.test.web.servlet.setup.MockMvcBuilders;import static org.springframework.security.test.web.servlet.setup.SecurityMockMvcConfigurers.springSecurity;import static org.springframework.test.web.servlet.request.MockMvcRequestBuilders.*;import static org.springframework.test.web.servlet.result.MockMvcResultMatchers.*;import static org.mockito.Mockito.*;import static com.aistock.prediction.portfolioquestion.QuestionEvidence.*;
@WebAppConfiguration @SpringJUnitConfig(PortfolioQuestionControllerTest.Config.class)
class PortfolioQuestionControllerTest {
 @Configuration @EnableWebSecurity @org.springframework.web.servlet.config.annotation.EnableWebMvc @Import({PredictionSecurityConfiguration.class,PortfolioQuestionController.class,ApiExceptionHandler.class})
 static class Config {@Bean PortfolioQuestionService service(){return mock(PortfolioQuestionService.class);}@Bean SessionIdentityClient identity(){return (input,token)->ApiResponse.success(new SessionIdentityClient.Identity(UUID.nameUUIDFromBytes(input.token().getBytes(java.nio.charset.StandardCharsets.UTF_8)),input.token().startsWith("b")?"ADMIN":"USER",false,1),"test");}@Bean static org.springframework.context.support.PropertySourcesPlaceholderConfigurer properties(){var c=new org.springframework.context.support.PropertySourcesPlaceholderConfigurer();var v=new Properties();v.setProperty("aistock.internal.token","fixture-service");c.setProperties(v);return c;}}
 @Autowired WebApplicationContext context;@Autowired PortfolioQuestionService service;MockMvc mvc;String session="a".repeat(43);MockCookie csrf=new MockCookie("XSRF-TOKEN","fixture-csrf");UUID op;
 @BeforeEach void setup(){reset(service);mvc=MockMvcBuilders.webAppContextSetup(context).apply(springSecurity()).build();op=UUID.randomUUID();}
 String body(){return "{\"operationId\":\""+op+"\",\"analysisId\":\""+ID+"\",\"question\":\"解释盈亏\",\"disclosureAccepted\":true}";}
 org.springframework.test.web.servlet.request.MockHttpServletRequestBuilder postBody(String body){return post("/api/v1/portfolio-questions").cookie(new MockCookie("AISTOCK_SESSION",session),csrf).header("Origin","http://127.0.0.1:15173").header("X-XSRF-TOKEN",csrf.getValue()).contentType("application/json").content(body);}
 @Test void anonymousForgedHeadersCsrfAndBadOriginCannotEnter()throws Exception{mvc.perform(get("/api/v1/portfolio-questions").header("X-User-Id",OWNER.toString()).header("X-Role","ADMIN")).andExpect(status().isUnauthorized());mvc.perform(post("/api/v1/portfolio-questions").cookie(new MockCookie("AISTOCK_SESSION",session)).content(body())).andExpect(status().isForbidden());mvc.perform(postBody(body()).with(q->{q.removeHeader("Origin");q.addHeader("Origin","https://untrusted.example");return q;})).andExpect(status().isForbidden());verifyNoInteractions(service);}
 @Test void strictBodyAndQueryRejectClientChosenOwnerAndFacts()throws Exception{for(String bad:List.of(body()+" {}",body().replace("}",",\"ownerId\":\"forged\"}"),body().replace("{","{\"question\":\"other\","),body().replace("true","\"true\""))){mvc.perform(postBody(bad)).andExpect(status().isBadRequest());}mvc.perform(postBody(" ".repeat(4097))).andExpect(status().isPayloadTooLarge());mvc.perform(postBody(body()).queryParam("ownerId","forged")).andExpect(status().isBadRequest());verifyNoInteractions(service);}
 @Test void authenticatedAdminUsesOnlyItsSessionIdentity()throws Exception{String admin="b".repeat(43);mvc.perform(postBody(body()).with(q->{q.setCookies(new MockCookie("AISTOCK_SESSION",admin),csrf);return q;})).andExpect(status().isOk());verify(service).generate(eq(UUID.nameUUIDFromBytes(admin.getBytes(java.nio.charset.StandardCharsets.UTF_8))),any());}
 @Test void rulesAndHistoryRequireExplicitOwnedAnalysisWithoutTriggeringGeneration()throws Exception{mvc.perform(get("/api/v1/portfolio-questions/rules").cookie(new MockCookie("AISTOCK_SESSION",session)).queryParam("analysisId",ID.toString()).queryParam("topic","PROFIT_FORMULA")).andExpect(status().isOk());mvc.perform(get("/api/v1/portfolio-questions").cookie(new MockCookie("AISTOCK_SESSION",session)).queryParam("analysisId",ID.toString())).andExpect(status().isOk());mvc.perform(get("/api/v1/portfolio-questions").cookie(new MockCookie("AISTOCK_SESSION",session)).queryParam("analysisId",ID.toString(),ID.toString())).andExpect(status().isBadRequest());verify(service,never()).generate(any(),any());}
}
